INSERT INTO shop_author VALUES(1,'Лесь','Подерв’янський',unistr('Людина, яка гармонійно поєднує в собі дві різні іпостасі: поважного художника та скандального, епатажного й шокуючого письменника. Він не заморочується над тим, які слова підбирати, що в усній, що в письмовій мові. Тому обережно: нецензурна лексика. Але він підходить до цього особливо, а всі гострі словечка майстерно прописує в кожному тексті. Творчість Леся Подерв’янського – яскраве зображення наших пороків, гріхів, національних рис, комплексів та проблем.\u000d\u000a\u000d\u000aВарто прочитати: «Рух життя, або Динамо», «Герой нашого часу», Гамлєт», «Павлік Морозов».'));
INSERT INTO shop_author VALUES(2,'Олександр','Михед',unistr('Молодий діяч у свої 27 вже досягнув небачених успіхів: публікації у провідних українських та іноземних ЗМІ, його проект «АмнезіЯ project: відкрита платформа» увійшов у сімку найкращих поетів світу.Після виходу його книг у світ, не в одного українського читача перевернулись уявлення про українську книжку. Адже Михед не вважає себе письменником у звичному значенні слова, а у своїй мультивекторній роботі він поєднує літературу, кінематограф й мистецтво у єдину гримучу суміш.\u000d\u000a\u000d\u000aВарто прочитати: «Астра», «Понтиїзм», АмнезіЯ».'));
INSERT INTO shop_author VALUES(3,'Любко','Дереш',unistr('Це, напевно, один із найзагадковіших та найекзотичніших письменників України. Свою першу книгу він написав ще у 15. За що його називають «феноменом української літератури». Творчість Дереша змушує людину думати, усвідомлювати себе, усвідомлювати світ, себе в ньому. Його книги важко назвати випадковими, а відокремити читача від автора майже неможливо.\u000d\u000a\u000d\u000aВарто прочитати: синайський цикл «Миротворець», «Остання любов Асури Махараджа», «Пісні про любов та вічність».'));
INSERT INTO shop_author VALUES(4,'Сергій','Жадан',unistr('«Голос Сходу», так часто називають Жадана. І не тільки тому, що він родом із Луганської області, а тому, що його література має присмак «пролетарщини», гнилої радянщини у свідомості покалічених людей. Естетика книг та їх демократичне наповнення свідчать про відвертого та щирого письменника. Мова пересипана гострим слівцем, але хто власне заперечить, що такою є вся українська мова сучасності. У його книгах – портрет українців: не зафотошоплений, брудний, чесний та до непристойності відвертий.\u000d\u000a\u000d\u000aВарто прочитати: проза – «Месопотамія», «Ворошиловоград», «Біґ Мак», «Гімн демократичної молоді», «Anarchy in the UKR», поезія – «Життя Марії», «Вогнепальні й ножові», «Ефіопія».\u000d\u000a\u000d\u000aТакож радимо прослухати спільний музичний альбом із «Собаками в космосі»: «Бийся за неї».'));
INSERT INTO shop_author VALUES(5,'Настасья','Мілевська',unistr('Тендітну харківську поетесу по праву вважають найемоційнішою на літературній сцені України. Її виступи – своєрідні моноспектаклі, які «прошивають» наскрізь слухача. Поезія залишає після себе незрівняний післясмак. Адже для неї написання – це своєрідний священний ритуал. Її творчість симбіоз літератури та театру, що вражає силою слова та неймовірною щирістю.\u000d\u000a\u000d\u000aВарто прочитати: «PSI*».'));
