CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE UNIQUE INDEX "shop_book_author_book_id_author_id_31dc9d3b_uniq" ON "shop_book_author" ("book_id", "author_id");
CREATE INDEX "shop_book_author_book_id_43bcbf5f" ON "shop_book_author" ("book_id");
CREATE INDEX "shop_book_author_author_id_22efc326" ON "shop_book_author" ("author_id");
CREATE UNIQUE INDEX "shop_book_category_book_id_category_id_774eb131_uniq" ON "shop_book_category" ("book_id", "category_id");
CREATE INDEX "shop_book_category_book_id_82a3ec1c" ON "shop_book_category" ("book_id");
